#define MATRIX_SIZE 1024
int matrix[MATRIX_SIZE][MATRIX_SIZE];

/* 
 * Spatial Locality Optimization: 
 * C/C++ is Row-Major. Iterate across rows (inner loop j) 
 * to utilize sequential memory access (cache line reuse).
*/
// Cache-friendly (Fast)
void row_major_access() {
    for (int i = 0; i < MATRIX_SIZE; ++i) {
        for (int j = 0; j < MATRIX_SIZE; ++j) {
            matrix[i][j] *= 2; // Accesses 0,0 then 0,1 then 0,2...
        }
    }
}

// Cache-unfriendly (Slow: High stride access)
void col_major_access() {
    for (int j = 0; j < MATRIX_SIZE; ++j) {
        for (int i = 0; i < MATRIX_SIZE; ++i) {
            matrix[i][j] *= 2; // Accesses 0,0 then 1,0 then 2,0... (Large stride miss)
        }
    }
}
